SDL_SetMainReady();
if (SDL_Init(SDL_INIT_VIDEO) != 0) {
    std::fprintf(stderr, "init failed: %s\n", SDL_GetError());
    SDL_Quit();
    return 1;
}

SDL_Event event{};
if (SDL_WaitEvent(&event) == 0) {
    exit_code = 1;
    break; // 전체 코드에서는 오류 메시지도 출력한다.
}
if (event.type == SDL_QUIT) running = false;
